pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Residual after placing the item
    let residual = post_residual as f64;
    let res_ratio = residual / bin_capacity as f64; // 0.0 = full, 1.0 = empty

    // Base score starts with the residual (higher residual → higher score)
    let mut score = residual;

    // 1. Strong quadratic penalty for large residuals – encourages tight packing
    score += 20.0 * res_ratio.powi(2);

    // 2. Penalize deviation from mean residual (balanced usage)
    let dev = residual - mean_residual;
    score += 0.5 * dev.abs();

    // 3. New‑bin candidate logic – only open if we are early or the residual
    //    after placement would be too large for any existing bin
    if bin_residual == bin_capacity {
        let open_ratio = open_bins_count as f64 / (total_items as f64 + 1.0);
        // If we still have many open bins, opening a new one is discouraged
        if open_ratio > 0.30 {
            score += 30.0;
        } else {
            // Penalize opening a new bin when residual would be large
            score += 10.0 + 15.0 * res_ratio;
        }
    }

    // 4. Fitting‑bin count weighting – prefer bins that have many fitting options
    if fitting_bins_count == 0 {
        score += 25.0;
    } else if fitting_bins_count > 6 {
        score -= 4.0;
    }

    // 5. Lookahead: reward bins that can also fit the next item
    if next_item_size > 0 {
        let diff = next_item_size as i32 - residual as i32;
        if diff > 0 {
            // If the next item fits, reward – larger reward for larger slack
            score -= 1.2 * diff as f64;
        } else {
            // If it does not fit, penalize proportionally to the shortfall
            score += 0.4 * (-diff as f64);
        }
    }

    // 6. Target utilization (~90% fill) – penalize deviation from target
    let target_util = 0.90;
    let util = 1.0 - res_ratio;
    score += (util - target_util).abs() * 15.0;

    // 7. Open‑bins log factor – discourage using many bins
    let open_factor = (open_bins_count as f64).ln().max(1.0);
    score += open_factor * 1.5;

    // 8. Progress‑based tweak – allow slightly more residual near the end
    let progress = step_index as f64 / (total_items as f64 + 1.0);
    if progress > 0.85 {
        score += (1.0 - progress) * res_ratio * 3.0;
    }

    // 9. Reduce variance: heavier penalty for squared deviation from mean
    score -= dev * dev * 0.03;

    // 10. Perfect bin reward
    if residual == 0.0 {
        score -= 12.0;
    }

    // Final scaling to keep scores in a similar range
    score * 0.92 + res_ratio * 0.08
}

