    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    let util = 1.0 - residual_ratio;
    let progress = step_index as f64 / (total_items as f64 + 1.0);
    let target_util = 0.75 + 0.15 * (1.0 - progress);

    let mut score = residual_ratio * residual_ratio * 25.0;
    score += (util - target_util).abs() * 20.0;

    if item_size as f64 > 0.8 * bin_capacity as f64 {
        score += 3.0;
    } else {
        score -= 0.5;
    }

    if open_bins_count > 0 {
        score += (open_bins_count as f64).ln() * 1.2 + 1.0;
    }

    if next_item_size > 0 {
        if post_residual < next_item_size {
            let diff = next_item_size - post_residual;
            score += diff as f64 * 3.0;
        } else {
            // safe: post_residual > 0 because post_residual >= next_item_size > 0
            score -= (next_item_size as f64 / post_residual as f64) * 1.5;
        }

        let potential_gap = post_residual as i32 - next_item_size as i32;
        if potential_gap > 0 {
            score += (potential_gap as f64 / bin_capacity as f64) * 6.0;
        }
    }

    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 3 {
        score += (fitting_bins_count as f64 - 3.0) * 1.0;
    }

    if bin_residual == bin_capacity && open_bins_count > 0 {
        let open_ratio = open_bins_count as f64 / (total_items as f64 + 1.0);
        score += 8.0 + 15.0 * open_ratio;
    }

    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.3;

    if post_residual == 0 {
        score -= 20.0;
    }

    if progress < 0.05 {
        score += (0.05 - progress) * 10.0;
    }

    score += (1.0 - progress) * residual_ratio * 6.0;

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Basic ratios and utilization
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    let util = 1.0 - residual_ratio;
    let progress = step_index as f64 / (total_items as f64 + 1.0);
    let target_util = 0.70 + 0.20 * (1.0 - progress);

    // Core penalty: larger residuals are worse
    let mut score = residual_ratio * residual_ratio * 28.0;

    // Utility deviation from target
    score += (util - target_util).abs() * 18.0;

    // Large item penalty: discourage packing very large items into a bin that could host them
    if item_size as f64 > 0.85 * bin_capacity as f64 {
        score += 4.0;
    } else {
        score -= 0.4;
    }

    // Open bin bias: prefer using existing bins but not too many
    if open_bins_count > 0 {
        score += (open_bins_count as f64).ln() * 1.0 + 0.8;
    }

    // Look‑ahead adjustment for the next item
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Not enough room for the next item; penalize heavily
            let diff = next_item_size - post_residual;
            score += diff as f64 * 3.5;
        } else {
            // Enough room; slight reward for spare space
            score -= (next_item_size as f64 / post_residual as f64) * 1.2;
        }

        // Reward bins that leave a small gap that matches the next item
        let gap = post_residual as i32 - next_item_size as i32;
        if gap > 0 {
            score += (gap as f64 / bin_capacity as f64) * 5.5;
        }
    }

    // Fitting bins count adjustment: very few bins are good, many bins are bad
    if fitting_bins_count == 1 {
        score -= 14.0;
    } else if fitting_bins_count > 4 {
        score += (fitting_bins_count as f64 - 4.0) * 0.8;
    }

    // New‑bin candidate handling
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let open_ratio = open_bins_count as f64 / (total_items as f64 + 1.0);
        // Prefer a new bin only if many bins are open and mean residual is low
        score += 7.0 + 12.0 * open_ratio;
    }

    // Mean residual deviation
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.25;

    // Zero residual is excellent
    if post_residual == 0 {
        score -= 18.0;
    }

    // Early‑stage penalty for high residuals
    if progress < 0.07 {
        score += (0.07 - progress) * 9.0;
    }

    // Final adjustment: encourage bins that keep residual proportional to progress
    score += (1.0 - progress) * residual_ratio * 5.0;

    score
}

