    // Item size relative to bin
    let item_ratio = item_size as f64 / bin_capacity as f64;
    if item_ratio > 0.95 {
        score += 5.0;
    } else {
        score -= 1.0;
    }

    // Open bins pressure
    if open_bins_count > 0 {
        let open_factor = ((open_bins_count as f64).ln() + 1.0).sqrt();
        score += open_factor * 1.5;
        // Extra penalty when many bins and residual still high
        if open_bins_count > 10 && residual_ratio > 0.4 {
            score += 30.0;
        }
    }

    // Look‑ahead for next item
    if next_item_size > 0 && post_residual < next_item_size {
        let diff = (next_item_size - post_residual) as f64;
        score += diff * 2.5;
    }

    // Target utilisation penalty
    let target_util = 0.85;
    let new_util = 1.0 - residual_ratio;
    score += (new_util - target_util).abs() * 30.0;

    // Fitting bins count adjustment
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 4 {
        score += 15.0;
    }

    // New‑bin candidate handling
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let open_ratio = open_bins_count as f64 / (total_items as f64 + 1.0);
        if open_ratio > 0.15 {
            score += 50.0;
        } else {
            score += 20.0;
        }
    }

    // Deviation from mean residual
    let dev = post_residual as f64 - mean_residual;
    score -= dev * dev * 0.07;

